int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD = 1000000007LL;
    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    long long ans = 0;
    for (int b = 0; b < 30; ++b) {
        long long c1 = 0;
        for (long long x : a) {
            if ((x >> b) & 1LL) ++c1;
        }
        long long c0 = n - c1;
        long long pairs = (c1 * c0) % MOD;
        long long weight = (1LL << b) % MOD;
        ans = (ans + pairs * weight) % MOD;
    }

    cout << ans << '\n';
    return 0;
}
