#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    if (!(cin >> R >> C)) return 0;

    vector<string> raw(R);
    for (int i = 0; i < R; ++i) {
        cin >> raw[i];
    }

    if (R < C) {
        vector<string> trans(C, string(R, '0'));
        for (int i = 0; i < R; ++i) {
            for (int j = 0; j < C; ++j) {
                trans[j][i] = raw[i][j];
            }
        }
        raw.swap(trans);
        swap(R, C);
    }

    vector<int> grid(R, 0);
    for (int i = 0; i < R; ++i) {
        int mask = 0;
        for (int j = 0; j < C; ++j) {
            if (raw[i][j] == '1') {
                mask |= (1 << j);
            }
        }
        grid[i] = mask;
    }

    int limit = 1 << C;
    int mask_all = limit - 1;
    vector<int> popcnt(limit, 0);
    for (int m = 1; m < limit; ++m) {
        popcnt[m] = popcnt[m >> 1] + (m & 1);
    }

    int best = R * C + 1;
    for (int first_press = 0; first_press < limit; ++first_press) {
        int prev_press = 0;
        int press = first_press;
        int flips = popcnt[press];
        bool ok = true;

        for (int r = 0; r < R; ++r) {
            if (flips >= best) {
                ok = false;
                break;
            }
            int cur = grid[r] ^ prev_press ^ press ^ ((press << 1) & mask_all) ^ (press >> 1);
            if (r == R - 1) {
                if (cur != 0) ok = false;
            } else {
                prev_press = press;
                press = cur;
                flips += popcnt[press];
            }
        }

        if (ok) {
            best = flips;
        }
    }

    cout << (best > R * C ? -1 : best) << '\n';
    return 0;
}
