import sys


def main() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    R = int(data[0])
    C = int(data[1])
    raw = data[2 : 2 + R]

    if R < C:
        raw = ["".join(raw[r][c] for r in range(R)) for c in range(C)]
        R, C = C, R

    grid = []
    for row in raw:
        mask = 0
        for j, ch in enumerate(row):
            if ch == "1":
                mask |= 1 << j
        grid.append(mask)

    limit = 1 << C
    mask_all = limit - 1
    popcnt = [0] * limit
    for m in range(1, limit):
        popcnt[m] = popcnt[m >> 1] + (m & 1)

    best = R * C + 1
    last_r = R - 1
    for first_press in range(limit):
        prev_press = 0
        press = first_press
        flips = popcnt[press]
        ok = True
        for r in range(R):
            if flips >= best:
                ok = False
                break
            cur = grid[r] ^ prev_press ^ press ^ ((press << 1) & mask_all) ^ (press >> 1)
            if r == last_r:
                if cur != 0:
                    ok = False
            else:
                prev_press = press
                press = cur
                flips += popcnt[press]
        if ok:
            best = flips

    sys.stdout.write(f"{-1 if best > R * C else best}\n")


